SELECT "id", "nombre", "direccion", "telefono", "rubro", "capacidades_operativas", "equipos_comercio", "arqueo_ciego_obligatorio", "fecha_creacion" FROM public."kioscos" ORDER BY "id";
SELECT "id", "auth_user_id", "kiosco_id", "nombre", "rol", "activo", "fecha_creacion" FROM public."usuarios" WHERE "kiosco_id" IS NOT NULL ORDER BY "id";
SELECT "id", "kiosco_id", "nombre", "color", "orden" FROM public."categorias" ORDER BY "id";
SELECT "id", "kiosco_id", "categoria_id", "proveedor_id", "codigo_barras", "descripcion", "precio_venta", "stock_actual", "stock_minimo", "es_favorito", "es_pesable", "unidad_medida", "plu_balanza", "es_combo", "es_retornable", "precio_envase", "nombre_envase", "requiere_vencimiento", "dias_alerta_vencimiento", "activo", "fecha_creacion", "fecha_actualizacion" FROM public."productos" ORDER BY "id";
SELECT "producto_id", "kiosco_id", "precio_costo", "fecha_actualizacion" FROM public."producto_costos" ORDER BY "producto_id";
SELECT "id", "kiosco_id", "combo_producto_id", "componente_producto_id", "cantidad", "created_at" FROM public."combo_items" ORDER BY "id";
SELECT "id", "kiosco_id", "nombre", "tipo", "producto_id", "categoria_id", "cantidad_minima", "cantidad_paga", "precio_unitario_promo", "descuento_porcentaje", "precio_combo", "items_combo", "dias_semana", "fecha_inicio", "fecha_fin", "activo", "created_at" FROM public."promociones" ORDER BY "id";
SELECT "id", "kiosco_id", "producto_id", "numero_lote", "fecha_vencimiento", "cantidad_inicial", "cantidad_actual", "fecha_ingreso", "activo" FROM public."lotes_producto" ORDER BY "id";
SELECT "id", "kiosco_id", "usuario_id", "fecha_apertura", "fecha_cierre", "monto_inicial", "monto_final_declarado", "monto_final_sistema", "diferencia", "estado", "notas_cierre" FROM public."sesiones_caja" WHERE "estado" = 'CERRADA' AND "fecha_cierre" IS NOT NULL ORDER BY "id";
SELECT "id", "kiosco_id", "usuario_id", "sesion_caja_id", "fecha_hora", "total", "estado", "notas", "sincronizado", "motivo_anulacion", "anulada_por", "anulada_en" FROM public."ventas" WHERE ("sesion_caja_id" IS NULL OR EXISTS (SELECT 1 FROM public."sesiones_caja" AS closed_session WHERE closed_session."id" = "ventas"."sesion_caja_id" AND closed_session."estado" = 'CERRADA' AND closed_session."fecha_cierre" IS NOT NULL)) ORDER BY "id";
SELECT "id", "venta_id", "producto_id", "cantidad", "precio_unitario", "subtotal", "sin_envase", "precio_envase_unitario" FROM public."detalles_venta" WHERE "venta_id" = ANY($1::uuid[]) ORDER BY "id";
SELECT "id", "venta_id", "medio_pago", "monto" FROM public."pagos_venta" WHERE "venta_id" = ANY($1::uuid[]) ORDER BY "id";
SELECT "id", "kiosco_id", "producto_id", "tipo", "cantidad", "motivo", "notas", "usuario_id", "fecha", "lote_producto_id" FROM public."movimientos_stock" ORDER BY "id";
SELECT "movimiento_id", "kiosco_id", "precio_costo" FROM public."movimiento_stock_costos" WHERE "movimiento_id" = ANY($1::uuid[]) ORDER BY "movimiento_id";
SELECT "id", "kiosco_id", "sesion_caja_id", "usuario_id", "tipo", "motivo", "monto", "descripcion", "fecha_hora" FROM public."movimientos_caja" WHERE EXISTS (SELECT 1 FROM public."sesiones_caja" AS closed_session WHERE closed_session."id" = "movimientos_caja"."sesion_caja_id" AND closed_session."estado" = 'CERRADA' AND closed_session."fecha_cierre" IS NOT NULL) AND "sesion_caja_id" = ANY($1::uuid[]) ORDER BY "id";
SELECT count(*)::bigint AS row_count FROM public."clientes";
SELECT count(*)::bigint AS row_count FROM public."movimientos_cuenta_corriente";
SELECT count(*)::bigint AS row_count FROM public."proveedores";
SELECT count(*)::bigint AS row_count FROM public."compras_proveedor";
SELECT count(*)::bigint AS row_count FROM public."detalles_compra";
SELECT count(*)::bigint AS row_count FROM public."pagos_proveedor";
